import java.util.*;

public class Main {
    // 模拟自动配置候选类
    static class AutoConfigCandidate {
        final String name;
        final String requiredClass;    // @ConditionalOnClass
        final String missingBeanType;  // @ConditionalOnMissingBean
        final String propertyName;     // @ConditionalOnProperty
        final String propertyValue;
        final String beanName;

        AutoConfigCandidate(String name, String requiredClass, String missingBeanType,
                            String propertyName, String propertyValue, String beanName) {
            this.name = name;
            this.requiredClass = requiredClass;
            this.missingBeanType = missingBeanType;
            this.propertyName = propertyName;
            this.propertyValue = propertyValue;
            this.beanName = beanName;
        }
    }

    // 模拟 AutoConfigurationImportSelector 的核心流程
    static class MiniAutoConfigSelector {
        final Set<String> classpath;
        final Set<String> registeredBeans;
        final Map<String, String> properties;
        final List<String> report = new ArrayList<>();

        MiniAutoConfigSelector(Set<String> classpath, Set<String> beans, Map<String, String> props) {
            this.classpath = new LinkedHashSet<>(classpath);
            this.registeredBeans = new LinkedHashSet<>(beans);
            this.properties = new LinkedHashMap<>(props);
        }

        // 模拟 selectImports: 去重 → exclude → 条件过滤 → 注册
        void processImports(List<AutoConfigCandidate> imports, Set<String> excludes) {
            // 步骤 1: 去重（同一个类可能被多个 jar 声明）
            Map<String, AutoConfigCandidate> deduplicated = new LinkedHashMap<>();
            for (AutoConfigCandidate c : imports) deduplicated.putIfAbsent(c.name, c);

            for (AutoConfigCandidate candidate : deduplicated.values()) {
                // 步骤 2: exclude 排除
                if (excludes.contains(candidate.name)) {
                    report.add("EXCLUDED " + candidate.name);
                    continue;
                }
                // 步骤 3: @ConditionalOnClass —— classpath 检查
                if (candidate.requiredClass != null && !classpath.contains(candidate.requiredClass)) {
                    report.add("NO_MATCH " + candidate.name + " (OnClass: " + candidate.requiredClass + " not on classpath)");
                    continue;
                }
                // 步骤 4: @ConditionalOnMissingBean —— 用户 Bean 优先
                if (candidate.missingBeanType != null && registeredBeans.contains(candidate.missingBeanType)) {
                    report.add("NO_MATCH " + candidate.name + " (OnMissingBean: user defined " + candidate.missingBeanType + ")");
                    continue;
                }
                // 步骤 5: @ConditionalOnProperty —— 属性开关
                if (candidate.propertyName != null &&
                    !Objects.equals(candidate.propertyValue, properties.get(candidate.propertyName))) {
                    report.add("NO_MATCH " + candidate.name + " (OnProperty: " + candidate.propertyName + " mismatch)");
                    continue;
                }
                // 全部条件通过，注册 BeanDefinition
                registeredBeans.add(candidate.beanName);
                report.add("MATCHED " + candidate.name + " -> registered '" + candidate.beanName + "'");
            }
        }
    }

    static List<AutoConfigCandidate> loadImports() {
        return List.of(
            new AutoConfigCandidate("DataSourceAutoConfiguration", "javax.sql.DataSource", "dataSource", null, null, "dataSource"),
            new AutoConfigCandidate("AcmeClientAutoConfiguration", "com.acme.Client", "acmeClient", "acme.enabled", "true", "acmeClient"),
            new AutoConfigCandidate("WebMvcAutoConfiguration", "jakarta.servlet.Servlet", null, null, null, "dispatcherServlet"),
            // 重复声明（模拟多个 jar 都声明同一个配置类）
            new AutoConfigCandidate("DataSourceAutoConfiguration", "javax.sql.DataSource", "dataSource", null, null, "dataSource")
        );
    }

    public static void main(String[] args) {
        // 场景 1: 正常匹配 + exclude
        MiniAutoConfigSelector s1 = new MiniAutoConfigSelector(
            Set.of("javax.sql.DataSource", "com.acme.Client", "jakarta.servlet.Servlet"),
            Set.of(),
            Map.of("acme.enabled", "true")
        );
        s1.processImports(loadImports(), Set.of("WebMvcAutoConfiguration"));
        System.out.println("=== exclude WebMvc, Acme enabled ===");
        System.out.println("beans: " + s1.registeredBeans);
        s1.report.forEach(r -> System.out.println("  " + r));
        assert s1.registeredBeans.equals(new LinkedHashSet<>(List.of("dataSource", "acmeClient")));

        // 场景 2: 用户已定义 dataSource → OnMissingBean 让默认退让
        MiniAutoConfigSelector s2 = new MiniAutoConfigSelector(
            Set.of("javax.sql.DataSource"),
            Set.of("dataSource"),  // 用户已注册
            Map.of()
        );
        s2.processImports(loadImports(), Set.of());
        System.out.println("\n=== user defined dataSource ===");
        System.out.println("beans: " + s2.registeredBeans);
        s2.report.forEach(r -> System.out.println("  " + r));
        assert s2.registeredBeans.contains("dataSource");
        assert s2.report.stream().anyMatch(r -> r.contains("OnMissingBean"));

        // 场景 3: classpath 缺少依赖
        MiniAutoConfigSelector s3 = new MiniAutoConfigSelector(
            Set.of(),
            Set.of(),
            Map.of()
        );
        s3.processImports(loadImports(), Set.of());
        System.out.println("\n=== empty classpath ===");
        System.out.println("beans: " + s3.registeredBeans);
        s3.report.forEach(r -> System.out.println("  " + r));
        assert s3.registeredBeans.isEmpty();
    }
}
